<?php
namespace App\Modules\Scheduling\Notifications;
use App\Modules\Scheduling\Models\Appointment;
use Illuminate\Bus\Queueable; use Illuminate\Contracts\Queue\ShouldQueue; use Illuminate\Notifications\Messages\MailMessage; use Illuminate\Notifications\Notification;
final class AppointmentConfirmedNotification extends Notification implements ShouldQueue { use Queueable; public function __construct(public Appointment $appointment,private string $cancelToken,private string $rescheduleToken){} public function via(object $notifiable):array{return ['mail'];} public function toMail(object $notifiable):MailMessage{$a=$this->appointment->loadMissing('eventType');$at=$a->scheduled_start_at->setTimezone($a->timezone);return (new MailMessage)->subject('Agendamento confirmado — '.$a->eventType->name)->greeting('Olá, '.$a->guest_name.'!')->line('Seu agendamento foi confirmado.')->line($at->format('d/m/Y H:i').' ('.$a->timezone.')')->line('Duração: '.$a->eventType->duration_minutes.' minutos')->line('Local: '.($a->eventType->location_value?:'Informado pelo responsável'))->action('Ver agendamento',route('scheduling.public.confirmation',$a))->line('Cancelar: '.route('scheduling.public.cancel.show',[$a,'token'=>$this->cancelToken]))->line('Reagendar: '.route('scheduling.public.reschedule.show',[$a,'token'=>$this->rescheduleToken]));}}
